def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def maxBstSubtreeSum(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    ok = [False] * n
    lo = [0] * n
    hi = [0] * n
    total = [0] * n
    best = 0
    for k in range(n - 1, -1, -1):
        v = vals[k]
        good = True
        mn = mx = v
        s = v
        l, r = left[k], right[k]
        if l != -1:
            if ok[l] and hi[l] < v:
                mn = lo[l]
                s += total[l]
            else:
                good = False
        if r != -1:
            if ok[r] and lo[r] > v:
                mx = hi[r]
                s += total[r]
            else:
                good = False
        ok[k], lo[k], hi[k], total[k] = good, mn, mx, s
        if good and s > best:
            best = s
    return best
